(function(){'use strict';let page=0,lastKey='',soundQuery='',soundCategory='All',preview=null;const oldFill=fillAssets;fillAssets=function(){const grid=$('#assetgrid');if(!grid)return;const key=category+':'+search;if(key!==lastKey){lastKey=key;page=0}const matches=M.assets.filter(a=>(category==='All'||a[2]===category)&&a[1].toLowerCase().includes(search.toLowerCase())),size=48;page=Math.min(page,Math.max(0,Math.ceil(matches.length/size)-1));grid.innerHTML='';for(const [type,label] of matches.slice(page*size,(page+1)*size)){const b=document.createElement('button');b.className='asset';b.draggable=true;b.title='Add '+label;b.innerHTML=`<canvas width="144" height="126"></canvas>${esc(label)}`;const o=M.make(type,72,63),s=Math.min(95/o.w,98/o.h);o.w*=s;o.h*=s;if(type==='text'){o.text='Aa';o.w=83;o.h=35}M.drawObject(b.querySelector('canvas').getContext('2d'),o,0);b.onclick=()=>addObject(type);b.ondragstart=e=>e.dataTransfer.setData('application/motionroom-object',type);grid.append(b)}let nav=$('#assetPages');if(!nav){nav=document.createElement('div');nav.id='assetPages';nav.className='pad';grid.parentNode.append(nav)}nav.innerHTML=`<p class="note">${matches.length} objects · page ${page+1} / ${Math.max(1,Math.ceil(matches.length/size))}</p><div class="row"><button id="assetsPrevious" ${page===0?'disabled':''}>Previous</button><button id="assetsNext" ${(page+1)*size>=matches.length?'disabled':''}>Next</button></div>`;$('#assetsPrevious').onclick=()=>{page--;fillAssets()};$('#assetsNext').onclick=()=>{page++;fillAssets()}};
function soundShelf(){const host=$('#libraryContent'),assets=[...MotionAudio.builtins(),...(project.audioAssets||[]).map(a=>({...a,category:'Imported'}))],categories=['All',...new Set(assets.map(a=>a.category||'Basics'))];host.innerHTML=`<div class="pad"><button id="importSound" class="primary wide">Import sound</button><p class="note">${assets.length} effects. Recorded foley comes from Kenney (CC0); other presets are synthesized offline. Preview before adding to the audio timeline.</p><input id="soundSearch" class="search" placeholder="Search sounds…" value="${esc(soundQuery)}"><select id="soundCategory">${categories.map(c=>`<option ${c===soundCategory?'selected':''}>${c}</option>`).join('')}</select></div><div id="soundShelf"></div>`;$('#importSound').onclick=()=>Studio.importSound();function cards(){const list=assets.filter(a=>(soundCategory==='All'||a.category===soundCategory)&&a.name.toLowerCase().includes(soundQuery.toLowerCase()));$('#soundShelf').innerHTML='';for(const asset of list){const card=document.createElement('div');card.className='soundcard';card.draggable=true;card.innerHTML=`<strong>${esc(asset.name)}</strong><small>${asset.duration.toFixed(2)}s</small><div class="row"><button class="preview-sound">▶ Preview</button><button class="add-sound">＋ Add</button></div>`;card.querySelector('.preview-sound').onclick=async()=>{try{preview?.stop();preview=await MotionAudio.previewAsset(asset)}catch(e){toast(e.message)}};card.querySelector('.add-sound').onclick=()=>AudioTimeline.add(asset);card.ondragstart=e=>e.dataTransfer.setData('application/motionroom-sound',asset.id);$('#soundShelf').append(card)}if(!list.length)$('#soundShelf').innerHTML='<p class="pad note">No matching sounds.</p>'}$('#soundSearch').oninput=e=>{soundQuery=e.target.value;cards()};$('#soundCategory').onchange=e=>{soundCategory=e.target.value;cards()};cards()}
const previous=renderLibrary;renderLibrary=function(){if(tab==='sounds')return soundShelf();previous()};if(tab==='assets')renderLibrary();
})();
